class Solution {
public:
    int minOperations(string s1, string s2, int x) {
        vector<int> idx;
        for (int i = 0; i < s1.size(); i++) if (s1[i] != s2[i]) idx.push_back(i);
        int m = idx.size();
        if (m % 2 != 0) return -1;
        vector<vector<int>> memo(m, vector<int>(m, -1));
        auto dfs = [&](auto& self, int i, int j) -> int {
            if (i > j) return 0;
            if (memo[i][j] != -1) return memo[i][j];
            int res = self(self, i + 1, j - 1) + x;
            res = min(res, self(self, i + 2, j) + idx[i + 1] - idx[i]);
            res = min(res, self(self, i, j - 2) + idx[j] - idx[j - 1]);
            return memo[i][j] = res;
        };
        return dfs(dfs, 0, m - 1);
    }
};

class Solution {
    public int minOperations(String s1, String s2, int x) {
        List<Integer> idx = new ArrayList<>();
        for (int i = 0; i < s1.length(); i++) if (s1.charAt(i) != s2.charAt(i)) idx.add(i);
        int m = idx.size();
        if (m % 2 != 0) return -1;
        Integer[][] memo = new Integer[m][m];
        return dfs(0, m - 1, idx, x, memo);
    }
    private int dfs(int i, int j, List<Integer> idx, int x, Integer[][] memo) {
        if (i > j) return 0;
        if (memo[i][j] != null) return memo[i][j];
        int res = dfs(i + 1, j - 1, idx, x, memo) + x;
        res = Math.min(res, dfs(i + 2, j, idx, x, memo) + idx.get(i + 1) - idx.get(i));
        res = Math.min(res, dfs(i, j - 2, idx, x, memo) + idx.get(j) - idx.get(j - 1));
        memo[i][j] = res;
        return res;
    }
}

