var minOperations = function(s1, s2, x) {
    const idx = [];
    for (let i = 0; i < s1.length; i++) if (s1[i] !== s2[i]) idx.push(i);
    const m = idx.length;
    if (m % 2 !== 0) return -1;
    const memo = Array.from({ length: m }, () => new Int32Array(m).fill(-1));
    function dfs(i, j) {
        if (i > j) return 0;
        if (memo[i][j] !== -1) return memo[i][j];
        let res = dfs(i + 1, j - 1) + x;
        res = Math.min(res, dfs(i + 2, j) + idx[i + 1] - idx[i]);
        res = Math.min(res, dfs(i, j - 2) + idx[j] - idx[j - 1]);
        memo[i][j] = res;
        return res;
    }
    return dfs(0, m - 1);
};
